// Tests for apps/index.js and base/services/launchApps.js (both generated by tools/catalog.py) and
// the apps' meta.js. Run: node apps/tests/index.test.js
// The index is the one line a new app folder adds: this checks it still matches the folders, on
// `main` too, where tools/ doesn't ship.
const fs = require("fs");
const path = require("path");
const assert = require("assert");

const { rootOf, make } = require("../../base/core/tests/qmljs.js");
const root = rootOf(__dirname);
const { lib, auto } = make(root);

const DIR = path.join(root, "apps");
const I = auto("apps/index.js");
const L = lib("base/services/launch.js", ["VTNC_APPS", "parse", "valid"]);

const index = fs.readFileSync(path.join(DIR, "index.js"), "utf8");
const imported = [...index.matchAll(/^\.import "([^"]+)\/meta\.js" as \w+$/gm)].map(m => m[1]);
// every folder with a meta.js: apps/<id>, plus the surfaces that are apps too (dashboard, settings)
const folders = fs.readdirSync(DIR)
    .filter(n => fs.existsSync(path.join(DIR, n, "meta.js")))
    .sort()
    .concat(["../dashboard", "../settings"].filter(n => fs.existsSync(path.join(DIR, n, "meta.js"))));

let passed = 0, failed = 0;
function test(name, fn) {
    try {
        fn();
        passed++;
    } catch (e) {
        failed++;
        console.log("FAIL " + name + "\n  " + e.message);
    }
}

test("the index imports exactly the folders that have a meta.js", () => {
    assert.deepStrictEqual(imported.sort(), folders.sort());
});

test("every app's folder has a View.qml", () => {
    assert.deepStrictEqual(Object.keys(I.APPS), Object.keys(I.FOLDERS));
    for (const id in I.FOLDERS)
        assert.ok(fs.existsSync(path.join(DIR, I.FOLDERS[id], "View.qml")), id + ": no View.qml");
});

test("every app describes itself", () => {
    for (const id in I.APPS) {
        const m = I.APPS[id];
        assert.ok(m.title, id + ": no title");
        assert.ok(m.icon, id + ": no icon");
        assert.strictEqual(typeof m.keepAlive, "boolean", id + ": keepAlive must be set");
        assert.strictEqual(typeof m.closeOnEsc, "boolean", id + ": closeOnEsc must be set");
    }
});

test("the launch targets are exactly the apps whose meta declares one", () => {
    const declared = Object.keys(I.APPS).filter(id => I.APPS[id].launch).sort();
    assert.deepStrictEqual(Object.keys(L.VTNC_APPS).sort(), declared);
    for (const id of declared) {
        assert.deepStrictEqual(L.VTNC_APPS[id], I.APPS[id].launch, id + ": launchApps.js is stale");
        assert.ok(L.valid("vtnc:" + id), id + ": not a valid launch target");
    }
});

console.log(passed + " passed, " + failed + " failed");
process.exit(failed ? 1 : 0);
